package au.monster.tracker;

import android.content.ContentValues;
import android.database.Cursor;
import android.database.sqlite.SQLiteDatabase;
import java.util.*;

public final class CatalogStore {
    private final Store store;
    public CatalogStore(Store store){this.store=store;}
    public record View(List<Catalog.Product> products,Map<String,Long> stock,List<Catalog.Shopping> shopping){}
    private static List<Catalog.Product> products(SQLiteDatabase db){List<Catalog.Product> out=new ArrayList<>();try(Cursor c=db.rawQuery("SELECT p.id,p.name,s.body FROM products p JOIN product_settings s ON s.product_id=p.id ORDER BY p.rowid",null)){while(c.moveToNext()){var m=Purchases.map(Json.parse(c.getString(2)));out.add(new Catalog.Product(c.getString(0),c.getString(1),Purchases.num(m,"minimum"),Purchases.num(m,"target"),Purchases.num(m,"packSize"),Purchases.num(m,"packCost"),Purchases.str(m,"supplier")));}}return Ledger.copy(out);}
    private static Map<String,List<Catalog.Allocation>> allocations(SQLiteDatabase db){Map<String,List<Catalog.Allocation>> result=new HashMap<>();try(Cursor c=db.rawQuery("SELECT event_id,product_id,quantity FROM event_products ORDER BY rowid",null)){while(c.moveToNext())result.computeIfAbsent(c.getString(0),key->new ArrayList<>()).add(new Catalog.Allocation(c.getString(1),c.getLong(2)));}return result;}
    private static List<Catalog.Transfer> transfers(SQLiteDatabase db){List<Catalog.Transfer> result=new ArrayList<>();try(Cursor c=db.rawQuery("SELECT body FROM flavour_transfers ORDER BY rowid",null)){while(c.moveToNext())result.add(Catalog.transfer(Json.parse(c.getString(0))));}return result;}
    public View view(){synchronized(store){var db=store.database();var snapshot=store.snapshot();var qty=Catalog.stock(snapshot.events(),allocations(db),transfers(db));var products=products(db);var documents=new BusinessStore(store).view();Map<String,Long> ordered=new HashMap<>();for(var d:documents.documents())if(!documents.cancelled().contains(d.id()))for(var l:d.lines())if(l.stock()&&l.productId()!=null)ordered.put(l.productId(),ordered.getOrDefault(l.productId(),0L)+l.cans()-documents.received().getOrDefault(l.id(),0L));List<Catalog.Shopping> shopping=new ArrayList<>();for(var p:products){long onHand=qty.getOrDefault(p.id(),0L);if(onHand<0)Purchases.bad("Historical flavour mapping needs reconciliation; no records were cleared.");shopping.add(Catalog.shopping(p,onHand,ordered.getOrDefault(p.id(),0L)));}return new View(products,Collections.unmodifiableMap(qty),Ledger.copy(shopping));}}
    public Catalog.Product lookup(String code){synchronized(store){String value=Catalog.barcode(code);String id;try(Cursor c=store.database().rawQuery("SELECT product_id FROM barcodes WHERE code=?",new String[]{value})){if(!c.moveToFirst())return null;id=c.getString(0);}for(var p:products(store.database()))if(p.id().equals(id))return p;return null;}}
    private static Map<String,Object> preferences(Catalog.Product p){Map<String,Object> m=new LinkedHashMap<>();m.put("minimum",p.minimum());m.put("target",p.target());m.put("packSize",p.packSize());m.put("packCost",p.packCost());m.put("supplier",p.supplier());return m;}
    private static void audit(SQLiteDatabase db,String action,String entity,Map<String,Object> body){long now=System.currentTimeMillis();ContentValues v=new ContentValues();v.put("id",Ledger.id());v.put("recorded_at",now);v.put("occurred_at",now);v.put("action",action);v.put("entity_id",entity);v.put("payload",Json.write(body));db.insertOrThrow("audit",null,v);}
    public void save(Catalog.Product product){synchronized(store){SQLiteDatabase db=store.database();db.beginTransaction();try{String old=null;try(Cursor c=db.rawQuery("SELECT name FROM products WHERE id=?",new String[]{product.id()})){if(c.moveToFirst())old=c.getString(0);}if(old==null){ContentValues v=new ContentValues();v.put("id",product.id());v.put("name",product.name());db.insertOrThrow("products",null,v);}else if(!old.equals(product.name()))Purchases.bad("Existing flavour names are immutable; create a new flavour instead.");ContentValues settings=new ContentValues();settings.put("product_id",product.id());settings.put("body",Json.write(preferences(product)));db.insertWithOnConflict("product_settings",null,settings,SQLiteDatabase.CONFLICT_REPLACE);Map<String,Object> payload=new LinkedHashMap<>(preferences(product));payload.put("name",product.name());audit(db,"product.preferences",product.id(),payload);db.setTransactionSuccessful();}finally{db.endTransaction();}}}
    public void assign(String code,String productId,boolean replace){synchronized(store){String value=Catalog.barcode(code);SQLiteDatabase db=store.database();db.beginTransaction();try{Catalog.Product old=lookup(value);if(old!=null&&!old.id().equals(productId)&&!replace)Purchases.bad("Barcode already belongs to "+old.name()+". Confirm reassignment explicitly.");if(old!=null&&old.id().equals(productId)){db.setTransactionSuccessful();return;}ContentValues v=new ContentValues();v.put("code",value);v.put("product_id",productId);db.insertWithOnConflict("barcodes",null,v,SQLiteDatabase.CONFLICT_REPLACE);Map<String,Object> m=new LinkedHashMap<>();m.put("code",value);m.put("previousProduct",old==null?null:old.id());m.put("productId",productId);audit(db,"barcode.assignment",productId,m);db.setTransactionSuccessful();}finally{db.endTransaction();}}}
    public void transfer(Catalog.Transfer t){synchronized(store){SQLiteDatabase db=store.database();db.beginTransaction();try{try(Cursor c=db.rawQuery("SELECT body FROM flavour_transfers WHERE id=?",new String[]{t.id()})){if(c.moveToFirst()){if(!c.getString(0).equals(Json.write(Catalog.transferMap(t))))Purchases.bad("Conflicting transfer ID.");db.setTransactionSuccessful();return;}}if(store.checkout()!=null)Purchases.bad("Resolve the pending card payment before counting or reassigning stock.");var stock=view().stock();if(stock.getOrDefault(t.from(),0L)<t.quantity())Purchases.bad("Not enough stock in the source flavour.");Set<String> ids=new HashSet<>();for(var p:products(db))ids.add(p.id());if(!ids.contains(t.from())||!ids.contains(t.to()))Purchases.bad("Unknown flavour.");ContentValues v=new ContentValues();v.put("id",t.id());v.put("body",Json.write(Catalog.transferMap(t)));db.insertOrThrow("flavour_transfers",null,v);audit(db,"stock.flavour_transfer",t.id(),Catalog.transferMap(t));db.setTransactionSuccessful();}finally{db.endTransaction();}}}
    public void stage(Ledger.Event event,String productId,boolean checkout){synchronized(store){SQLiteDatabase db=store.database();db.beginTransaction();try{for(var existing:store.snapshot().events())if(existing.id().equals(event.id())){if(!Ledger.same(existing,event))Purchases.bad("Conflicting transaction ID.");var saved=Catalog.forEvent(existing,allocations(db));if(saved.size()!=1||!saved.get(0).productId().equals(productId))Purchases.bad("Conflicting transaction flavour.");db.setTransactionSuccessful();return;}plan(db,event,Ledger.list(new Catalog.Allocation(productId,event.quantity())));Ledger.validate(event,store.snapshot().events());beforeAppend(store,event,store.snapshot().events());if(checkout)store.beginCheckout(event);else store.stage(event);db.setTransactionSuccessful();}finally{db.endTransaction();}}}
    static void plan(SQLiteDatabase db,Ledger.Event event,List<Catalog.Allocation> value){Map<String,List<Catalog.Allocation>> map=new HashMap<>();map.put(event.id(),value);Catalog.forEvent(event,map);String json=Json.write(Catalog.allocationMaps(value));try(Cursor c=db.rawQuery("SELECT body FROM catalog_plans WHERE event_id=?",new String[]{event.id()})){if(c.moveToFirst()&&!c.getString(0).equals(json))Purchases.bad("Pending transaction flavour changed.");}ContentValues v=new ContentValues();v.put("event_id",event.id());v.put("body",json);db.insertWithOnConflict("catalog_plans",null,v,SQLiteDatabase.CONFLICT_REPLACE);}
    static void beforeAppend(Store store,Ledger.Event event,List<Ledger.Event> current){SQLiteDatabase db=store.database();Map<String,List<Catalog.Allocation>> map=allocations(db);try(Cursor c=db.rawQuery("SELECT body FROM catalog_plans WHERE event_id=?",new String[]{event.id()})){if(c.moveToFirst())map.put(event.id(),Catalog.allocations(Json.parse(c.getString(0))));}List<Ledger.Event> trial=new ArrayList<>(current);trial.add(event);var stock=Catalog.stock(trial,map,transfers(db));for(var value:stock.values())if(value<0)Purchases.bad("Not enough stock in that flavour. Choose the correct flavour or correct its stock count.");Set<String> ids=new HashSet<>();for(var p:products(db))ids.add(p.id());for(var id:stock.keySet())if(!ids.contains(id))Purchases.bad("Flavour does not exist.");}
    static void afterAppend(SQLiteDatabase db,Ledger.Event event){try(Cursor c=db.rawQuery("SELECT body FROM catalog_plans WHERE event_id=?",new String[]{event.id()})){if(c.moveToFirst()){var values=Catalog.allocations(Json.parse(c.getString(0)));for(var a:values){ContentValues v=new ContentValues();v.put("event_id",event.id());v.put("product_id",a.productId());v.put("quantity",a.quantity());db.insertOrThrow("event_products",null,v);}Map<String,Object> payload=new LinkedHashMap<>();payload.put("eventId",event.id());payload.put("allocations",Catalog.allocationMaps(values));audit(db,"stock.flavour_event",event.id(),payload);db.delete("catalog_plans","event_id=?",new String[]{event.id()});}}}
    public Map<String,Object> export(){synchronized(store){SQLiteDatabase db=store.database();Map<String,Object> out=new LinkedHashMap<>();List<Object> ps=new ArrayList<>();for(var p:products(db)){Map<String,Object> m=new LinkedHashMap<>(preferences(p));m.put("id",p.id());m.put("name",p.name());ps.add(m);}out.put("products",ps);List<Object> bs=new ArrayList<>();try(Cursor c=db.rawQuery("SELECT code,product_id FROM barcodes ORDER BY code",null)){while(c.moveToNext()){Map<String,Object> m=new LinkedHashMap<>();m.put("code",c.getString(0));m.put("productId",c.getString(1));bs.add(m);}}out.put("barcodes",bs);List<Object> rows=new ArrayList<>();for(var entry:allocations(db).entrySet()){Map<String,Object> m=new LinkedHashMap<>();m.put("eventId",entry.getKey());m.put("allocations",Catalog.allocationMaps(entry.getValue()));rows.add(m);}out.put("allocations",rows);List<Object> moves=new ArrayList<>();for(var t:transfers(db))moves.add(Catalog.transferMap(t));out.put("transfers",moves);return out;}}
    public void restore(Map<String,Object> data,List<Ledger.Event> events){if(data==null)return;CatalogBackup.validate(data,events);SQLiteDatabase db=store.database();for(Object value:Purchases.list(data.get("products"))){var m=Purchases.map(value);var p=CatalogBackup.product(m);String name=null;try(Cursor c=db.rawQuery("SELECT name FROM products WHERE id=?",new String[]{p.id()})){if(c.moveToFirst())name=c.getString(0);}if(name==null){ContentValues row=new ContentValues();row.put("id",p.id());row.put("name",p.name());db.insertOrThrow("products",null,row);ContentValues settings=new ContentValues();settings.put("product_id",p.id());settings.put("body",Json.write(preferences(p)));db.insertOrThrow("product_settings",null,settings);}else if(!name.equals(p.name()))Purchases.bad("Conflicting flavour identity. Restore cancelled.");}
        for(Object value:Purchases.list(data.get("barcodes"))){var m=Purchases.map(value);Catalog.Product old=lookup(Purchases.str(m,"code"));String id=Purchases.str(m,"productId");if(old!=null&&!old.id().equals(id))Purchases.bad("Barcode conflict in restore.");if(old==null){ContentValues v=new ContentValues();v.put("code",Purchases.str(m,"code"));v.put("product_id",id);db.insertOrThrow("barcodes",null,v);}}
        for(Object value:Purchases.list(data.get("allocations"))){var m=Purchases.map(value);String eventId=Purchases.str(m,"eventId");List<Catalog.Allocation> incoming=Catalog.allocations(m.get("allocations"));var existing=allocations(db).get(eventId);if(existing!=null){if(!Json.write(Catalog.allocationMaps(existing)).equals(Json.write(Catalog.allocationMaps(incoming))))Purchases.bad("Historical flavour conflict. Nothing restored.");}else for(var a:incoming){ContentValues v=new ContentValues();v.put("event_id",eventId);v.put("product_id",a.productId());v.put("quantity",a.quantity());db.insertOrThrow("event_products",null,v);}}
        for(Object value:Purchases.list(data.get("transfers"))){var t=Catalog.transfer(value);String old=null;try(Cursor c=db.rawQuery("SELECT body FROM flavour_transfers WHERE id=?",new String[]{t.id()})){if(c.moveToFirst())old=c.getString(0);}String json=Json.write(Catalog.transferMap(t));if(old==null){ContentValues v=new ContentValues();v.put("id",t.id());v.put("body",json);db.insertOrThrow("flavour_transfers",null,v);}else if(!old.equals(json))Purchases.bad("Conflicting flavour transfer.");}var stock=Catalog.stock(events,allocations(db),transfers(db));for(long q:stock.values())if(q<0)Purchases.bad("Combined restore would make a flavour negative. Current records are unchanged.");
    }
}
